func subtaskMoveUp(tasks []authorization.Subtask, index int) []string {
	ids := make([]string, len(tasks))
	for i, t := range tasks {
		ids[i] = t.ID
	}
	ids[index-1], ids[index] = ids[index], ids[index-1]
	return ids
}

